#include <iostream>
using namespace std;

int fibonacci(int n) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else {
        return fibonacci(n-1) + fibonacci(n-2);
    }
}

int main() {
    int n;
    cout << "Enter the number of the Fibonacci number you want to find: ";
    cin >> n;

    int result = fibonacci(n);

    cout << "The " << n << "th Fibonacci number is: " << result << endl;

    return 0;
}
```

In this program, we define a function `fibonacci()` that takes an integer `n` as its argument and returns the nth Fibonacci number.

The base cases are when `n` is 0 or 1, in which case we return 0 and 1, respectively.

For any other value of `n`, we call the `fibonacci()` function recursively with `n-1` and `n-2` as arguments, and add the results together.

